CREATE   PROCEDURE [synapse_ce].[usp_Update_apuk_caseannualreturn]
AS
BEGIN
	UPDATE tgt SET 
		tgt.[apuk_ageofcase] = DATEDIFF(DAY, stg.createdon, COALESCE(stg.apuk_caseclosuredate,GETDATE())),--stg.[apuk_ageofcase],
		tgt.[apuk_areaofbreach] = stg.[apuk_areaofbreach],
		tgt.[apuk_areaofbreach_entitytype] = stg.[apuk_areaofbreach_entitytype],
		tgt.[apuk_areaofbreach2] = stg.[apuk_areaofbreach2],
		tgt.[apuk_areaofbreach2_entitytype] = stg.[apuk_areaofbreach2_entitytype],
		tgt.[apuk_areaofbreach2name] = stg.[apuk_areaofbreach2name],
		tgt.[apuk_areaofbreach3] = stg.[apuk_areaofbreach3],
		tgt.[apuk_areaofbreach3_entitytype] = stg.[apuk_areaofbreach3_entitytype],
		tgt.[apuk_areaofbreach3name] = stg.[apuk_areaofbreach3name],
		tgt.[apuk_areaofbreachname] = stg.[apuk_areaofbreachname],
		tgt.[apuk_areaofpractice] = stg.[apuk_areaofpractice],
		tgt.[apuk_areaofpractice_entitytype] = stg.[apuk_areaofpractice_entitytype],
		tgt.[apuk_areaofpracticename] = stg.[apuk_areaofpracticename],
