		tgt.[apuk_casedescription] = stg.[apuk_casedescription],
		tgt.[apuk_casegroupreference] = stg.[apuk_casegroupreference],
		tgt.[apuk_caseorigin] = stg.[apuk_caseorigin],
		tgt.[apuk_casestatus] = stg.[apuk_casestatus],
		tgt.[apuk_casetype] = stg.[apuk_casetype],
		tgt.[apuk_escalationlevel] = stg.[apuk_escalationlevel],
		tgt.[apuk_failreason] = stg.[apuk_failreason],
		tgt.[apuk_name] = stg.[apuk_name],
		tgt.[apuk_outcome] = stg.[apuk_outcome],
		tgt.[apuk_primarylocationid] = stg.[apuk_primarylocationid],
