		tgt.[apuk_regulatedfirmidname] = stg.[apuk_regulatedfirmidname],
		tgt.[apuk_regulatedfirmidyominame] = stg.[apuk_regulatedfirmidyominame],
		tgt.[apuk_regulatedindividualid] = stg.[apuk_regulatedindividualid],
		tgt.[apuk_regulatedindividualid_entitytype] = stg.[apuk_regulatedindividualid_entitytype],
		tgt.[apuk_regulatedindividualidname] = stg.[apuk_regulatedindividualidname],
		tgt.[apuk_regulatedindividualidyominame] = stg.[apuk_regulatedindividualidyominame],
		tgt.[apuk_regulatedschemeid] = stg.[apuk_regulatedschemeid],
		tgt.[apuk_regulatedschemeid_entitytype] = stg.[apuk_regulatedschemeid_entitytype],
