		tgt.[apuk_regulatoryreturnidname] = stg.[apuk_regulatoryreturnidname],
		tgt.[apuk_responsibleprincipal] = stg.[apuk_responsibleprincipal],
		tgt.[apuk_responsibleprincipal_entitytype] = stg.[apuk_responsibleprincipal_entitytype],
		tgt.[apuk_responsibleprincipalname] = stg.[apuk_responsibleprincipalname],
		tgt.[apuk_responsibleprincipalyominame] = stg.[apuk_responsibleprincipalyominame],
